<script lang="ts">
  import {tick} from 'svelte';
  import type {DashboardTimelineSelection} from '../../../../../src/services/dashboard.ts';
  import type {RelatedSpecPage} from '../../../../../src/services/workspace-timeline-contract.ts';
  let {selection,pages,clearHref,pageHref,onNavigate}:{selection:DashboardTimelineSelection;pages:{direct:RelatedSpecPage;transitive:RelatedSpecPage};clearHref:string;pageHref:(kind:'direct'|'transitive',page:number)=>string;onNavigate:(event:MouseEvent)=>void}=$props();
  let disclosure:HTMLDetailsElement,keepOpen=false,restore:{kind:string;direction:string}|undefined;
  const nondefault=$derived(pages.direct.requestedPage>1||pages.transitive.requestedPage>1);
  const entries=$derived([{kind:'direct' as const,label:'Direct',page:pages.direct},{kind:'transitive' as const,label:'Transitive',page:pages.transitive}]);
  async function pageActivated(kind:string,direction:string){keepOpen=true;restore={kind,direction};}
  $effect(()=>{const direct=pages.direct,transitive=pages.transitive;void direct;void transitive;if(disclosure&&keepOpen)disclosure.open=true;if(restore){const target=restore;restore=undefined;void tick().then(()=>{const node=disclosure.querySelector<HTMLElement>(`[data-category="${target.kind}"] [data-direction="${target.direction}"]`);(node??disclosure.querySelector<HTMLElement>(`[data-category="${target.kind}"] .range`))?.focus({preventScroll:true});});}});
</script>
<section class="trace-summary" aria-label="Selected dependency trace"><div class="trace-title"><strong>Trace: {selection.taskId}</strong><span title={selection.title}>{selection.title}</span><a href={clearHref}>Clear trace</a></div><div class="counts">{#each [['Direct dependencies',selection.directDependencyIds.length],['Transitive dependencies',selection.transitiveDependencyIds.length],['Direct dependents',selection.directDependentIds.length],['Transitive dependents',selection.transitiveDependentIds.length],['Direct blocked dependents',selection.directBlockedDependentIds.length],['Transitive blocked dependents',selection.transitiveBlockedDependentIds.length]] as [label,count]}<span>{label} <strong>{count}</strong></span>{/each}</div>
  <details bind:this={disclosure} open={nondefault}><summary>Related specs ({pages.direct.total} direct, {pages.transitive.total} transitive)</summary><div class="related-lists">{#each entries as entry}<section data-category={entry.kind}><h2>{entry.label} related specs</h2><p class="range" tabindex="-1">{entry.page.total?(entry.page.page-1)*50+1:0}–{Math.min(entry.page.page*50,entry.page.total)} of {entry.page.total}</p><ul>{#each entry.page.ids as id}<li><a href={`/specs/${encodeURIComponent(id)}`}>{id}</a></li>{/each}</ul>{#if !entry.page.total}<p>None</p>{/if}<nav aria-label={`${entry.label} related-spec pages`}>{#if entry.page.page>1}<a data-direction="previous" href={pageHref(entry.kind,entry.page.page-1)} onclick={event=>{pageActivated(entry.kind,'previous');onNavigate(event);}}>Previous</a>{/if}{#if entry.page.page<entry.page.totalPages}<a data-direction="next" href={pageHref(entry.kind,entry.page.page+1)} onclick={event=>{pageActivated(entry.kind,'next');onNavigate(event);}}>Next</a>{/if}</nav></section>{/each}</div></details>
</section>
<style>.trace-summary{flex-shrink:0;border:1px solid var(--border-control);border-left:3px solid var(--accent);border-radius:.25rem;padding:.5rem .625rem;margin-bottom:.5rem;background:var(--surface);font-size:.75rem}.trace-title,.counts{display:flex;align-items:center;flex-wrap:wrap;gap:.375rem 1rem}.trace-title>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;max-width:36rem}.trace-title>a{margin-left:auto}.counts{margin:.375rem 0;color:var(--text-muted)}.counts strong{color:var(--text);font-variant-numeric:tabular-nums}a{display:inline-flex;align-items:center;min-height:24px;color:var(--accent)}summary{cursor:pointer;min-height:24px;color:var(--text-muted)}.related-lists{display:grid;grid-template-columns:repeat(auto-fit,minmax(14rem,1fr));gap:1rem;max-height:16rem;overflow:auto}.related-lists h2{font:600 .75rem var(--body-font);margin:.5rem 0}.related-lists p{color:var(--text-muted);margin:.25rem 0}.related-lists ul{display:flex;flex-wrap:wrap;gap:.25rem .75rem;list-style:none;padding:0;margin:.5rem 0}.related-lists nav{display:flex;gap:1rem}@media(pointer:coarse){a,summary{min-height:44px}}</style>
